import React from 'react';

const Contact = () => {
  return (
    <section id="contact" style={{ padding: '50px 20px', textAlign: 'center', background: '#f5f5f5' }}>
      <h2>Contact Me</h2>
      <p>Email: <a href="mailto:krinapatel@example.com">krinapatel@example.com</a></p>
      <p>LinkedIn: <a href="https://www.linkedin.com/in/krinapatel" target="_blank" rel="noopener noreferrer">linkedin.com/in/krinapatel</a></p>
      <p>GitHub: <a href="https://github.com/krinapatel" target="_blank" rel="noopener noreferrer">github.com/krinapatel</a></p>
    </section>
  );
};

export default Contact;
